import sqlite3
def insert_valid(db,rows):
    count=0
    with db:
        db.execute('begin')
        for key,amount in rows:
            db.execute('savepoint item')
            try:
                db.execute('insert into ledger values (?,?)',(key,amount));count+=1
            except sqlite3.IntegrityError:db.execute('rollback to item')
            finally:db.execute('release item')
    return count

