class Bucket:
    def __init__(self,capacity,rate,start=0):
        if capacity<1 or rate<0:raise ValueError('invalid bucket')
        self.capacity=capacity;self.rate=rate;self.tokens=float(capacity);self.last=start
    def allow(self,now):
        if now<self.last:raise ValueError('backwards clock')
        self.tokens=min(self.capacity,self.tokens+(now-self.last)*self.rate);self.last=now
        if self.tokens<1:return False
        self.tokens-=1;return True

