class Breaker:
    def __init__(self,threshold,cooldown):
        if threshold<1 or cooldown<0:raise ValueError('invalid policy')
        self.threshold=threshold;self.cooldown=cooldown;self.failures=0;self.state='closed';self.opened=0
    def permit(self,now):
        if self.state=='closed':return True
        if self.state=='open' and now-self.opened>=self.cooldown:
            self.state='half';return True
        return False
    def success(self):self.state='closed';self.failures=0
    def failure(self,now):
        self.failures+=1
        if self.state=='half' or self.failures>=self.threshold:self.state='open';self.opened=now

