def retry_plan(budget,attempt,delays):
    delays=list(delays)
    if budget<0 or attempt<0 or any(d<0 for d in delays):raise ValueError('negative budget')
    elapsed=attempt;result=[]
    if elapsed>budget:return result
    for delay in delays:
        if elapsed+delay+attempt>budget:break
        result.append(delay);elapsed+=delay+attempt
    return result

