def bounded_body(chunks,limit):
    if limit<0:raise ValueError('negative limit')
    parts=[];size=0
    for chunk in chunks:
        size+=len(chunk)
        if size>limit:raise ValueError('body too large')
        parts.append(chunk)
    return b''.join(parts)

