from pathlib import Path
def safe_path(root,name):
    relative=Path(name)
    if relative.is_absolute() or ".." in relative.parts or "\\" in name or "\x00" in name:raise ValueError("invalid relative path")
    base=Path(root).resolve();candidate=(base/relative).resolve()
    if candidate!=base and base not in candidate.parents:raise ValueError("outside root")
    return candidate

